from __future__ import annotations


def build_trading_records_ui() -> str:
    return r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>统一交易记录 V3.26</title><!-- 统一交易记录 V3.23 兼容入口 -->
<style>:root{--bg:#08111f;--panel:#101a2c;--line:#263955;--text:#e7f0ff;--muted:#91a6c5;--blue:#3b82f6}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:"Segoe UI","Microsoft YaHei",Arial,sans-serif}header{height:58px;display:flex;align-items:center;gap:12px;padding:0 18px;background:#0b1424;border-bottom:1px solid var(--line)}.brand{font-size:20px;font-weight:900}.grow{flex:1}a{color:#bfdbfe;text-decoration:none}.wrap{padding:12px}.toolbar,.tabs{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:10px}.toolbar input,.toolbar select,.toolbar button{padding:8px 10px;border:1px solid #334969;border-radius:7px;background:#111d31;color:var(--text)}button{cursor:pointer;font-weight:800}.primary,.tab.active{background:var(--blue)!important}.summary{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:8px;margin-bottom:10px}.card,.panel{background:var(--panel);border:1px solid var(--line);border-radius:8px}.card{padding:10px;min-width:0}.card span{display:block;color:var(--muted);font-size:12px}.card b{display:block;font-size:19px;margin-top:5px;overflow-wrap:anywhere}.tab{border:0;padding:8px 12px;background:#233654;color:var(--text);border-radius:7px}.pane{display:none}.pane.active{display:block}.table-wrap{overflow:auto;max-height:calc(100vh - 250px);border-radius:8px}table{width:100%;min-width:1250px;border-collapse:collapse;table-layout:fixed;font-size:12px}th,td{padding:8px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top;overflow-wrap:anywhere}th{position:sticky;top:0;background:#14223a;color:#9fd4ff}.ok{color:#86efac}.bad{color:#fca5a5}.muted{color:var(--muted)}@media(max-width:1100px){.summary{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:900px){.summary{grid-template-columns:repeat(2,minmax(0,1fr))}header{height:auto;min-height:58px;flex-wrap:wrap;padding:10px}}</style></head>
<body><header><div class="brand">统一交易记录 V3.26</div><div class="grow"></div><a href="/auto-trading">总控台</a><a href="/backtest">历史回测</a><a href="/realtime-paper">实时模拟</a><a href="/live-trading">真实交易</a></header><div class="wrap">
<div class="toolbar"><select id="mode"><option value="">全部模式</option><option value="backtest">历史回测</option><option value="realtime_paper">实时模拟</option><option value="live">真实交易</option></select><select id="status"><option value="">全部状态</option><option value="filled">已成交</option><option value="needs_confirmation">待确认</option><option value="risk_blocked">风控拦截</option><option value="cancelled">已撤单</option><option value="rejected">已拒单</option></select><input id="symbol" placeholder="股票代码"><input id="session" placeholder="会话 ID"><button class="primary" onclick="loadAll(this)">查询</button><button onclick="exportRows()">导出JSON</button><span class="muted">每笔买入、卖出、费用、盈亏和持仓批次可独立追溯。</span></div>
<div id="summary" class="summary"></div><div class="tabs"><button class="tab active" data-tab="records" onclick="openTab('records')">统一事件流水</button><button class="tab" data-tab="ledger" onclick="openTab('ledger')">成交账本</button><button class="tab" data-tab="lots" onclick="openTab('lots')">持仓批次</button><button class="tab" data-tab="equity" onclick="openTab('equity')">账户快照</button></div>
<section id="pane-records" class="pane active panel"><div class="table-wrap"><table><thead><tr><th>时间</th><th>类型</th><th>模式</th><th>代码</th><th>方向/状态</th><th>价格</th><th>数量</th><th>金额/市值</th><th>费用</th><th>盈亏</th><th>收益率</th><th>成本</th><th>摘要</th></tr></thead><tbody id="recordRows"></tbody></table></div></section>
<section id="pane-ledger" class="pane panel"><div class="table-wrap"><table><thead><tr><th>发生时间</th><th>模式</th><th>会话</th><th>代码</th><th>账务类型</th><th>方向</th><th>股数</th><th>价格</th><th>金额</th><th>订单 ID</th><th>成交 ID</th><th>来源</th></tr></thead><tbody id="ledgerRows"></tbody></table></div></section>
<section id="pane-lots" class="pane panel"><div class="table-wrap"><table><thead><tr><th>建仓时间</th><th>平仓时间</th><th>代码</th><th>原始股数</th><th>剩余股数</th><th>成本价</th><th>状态</th><th>来源订单</th><th>来源成交</th><th>会话</th></tr></thead><tbody id="lotRows"></tbody></table></div></section>
<section id="pane-equity" class="pane panel"><div class="table-wrap"><table><thead><tr><th>时间</th><th>模式</th><th>账户</th><th>现金</th><th>可用资金</th><th>持仓市值</th><th>总权益</th><th>已实现盈亏</th><th>浮动盈亏</th><th>收益率</th><th>数据源</th></tr></thead><tbody id="equityRows"></tbody></table></div></section>
<p class="muted">研究辅助，不构成投资建议；真实交易需用户自行确认合规与风险。</p></div>
<script>const $=id=>document.getElementById(id);let exportData=[];const labels={backtest:'历史回测',realtime_paper:'实时模拟',paper:'实时模拟',live:'真实交易',buy:'买入',sell:'卖出',hold:'观察',reduce:'减仓',commission:'佣金',tax:'税费',slippage:'滑点',realized_pnl:'已实现盈亏',unrealized_pnl:'浮动盈亏',cash:'现金变动',open:'持有中',closed:'已平仓',signal_created:'信号已生成',prechecked:'预检查通过',risk_blocked:'风控拦截',needs_confirmation:'等待人工确认',confirmed:'已确认',submitted:'已提交',accepted:'已受理',partially_filled:'部分成交',filled:'已成交',cancel_requested:'申请撤单',cancelled:'已撤单',rejected:'已拒单',expired:'已过期',failed:'处理失败',unknown:'状态未知',reconciled:'已对账',realtime_session_superseded:'旧模拟会话已停止',realtime_session_reconfigured:'模拟参数已更新',realtime_session_kill_switch:'模拟安全开关变更',realtime_session_start:'模拟会话启动',realtime_session_pause:'模拟暂停',realtime_session_resume:'模拟恢复',realtime_paper_scheduler_error:'模拟调度异常',realtime_paper_start:'模拟会话启动',realtime_paper_tick:'模拟轮询',realtime_paper_pause:'模拟暂停',realtime_paper_resume:'模拟恢复',realtime_paper_stop:'模拟停止',auto_trading_start_paper:'总控台启动模拟',backtest_v323_run:'历史回测运行',daily_position_review_scheduler_error:'持仓复核调度异常',daily_position_review_run:'持仓复核完成',live_watch_added:'加入实盘观察池',kill_switch:'实盘安全开关',mobile_alert:'移动端提醒',tonghuashun_client_launched:'同花顺客户端已启动',tonghuashun_reminder_created:'同花顺委托提醒已创建',manual_test:'人工测试',signal_generated:'生成交易信号',order_submitted:'提交委托',order_filled:'委托成交',risk_check:'风险检查',audit_events:'审计',chart_markers:'图表标注',score_provenance:'评分溯源',manual_confirmations:'人工确认',account_snapshots:'账户快照',positions:'持仓快照',orders:'委托',fills:'成交'};function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}function cn(v){const key=String(v??'');return labels[key]||key||'--'}function cnText(v){let text=String(v??'');Object.entries(labels).sort((a,b)=>b[0].length-a[0].length).forEach(([key,value])=>{text=text.split(key).join(value)});return text||'--'}function money(v){const n=Number(v);return Number.isFinite(n)?n.toLocaleString('zh-CN',{maximumFractionDigits:2}):'--'}function pct(v){const n=Number(v);return Number.isFinite(n)?n.toFixed(2)+'%':'--'}function cls(v){const n=Number(v);return n>0?'ok':n<0?'bad':''}async function api(u){return fetch(u).then(r=>r.json())}function query(extra={}){const p=new URLSearchParams({mode:$('mode').value,symbol:$('symbol').value,session_id:$('session').value,limit:'1000',...extra});for(const [k,v] of [...p])if(!v)p.delete(k);return p}function openTab(n){document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x.dataset.tab===n));document.querySelectorAll('.pane').forEach(x=>x.classList.toggle('active',x.id==='pane-'+n));exportData=window['data_'+n]||[]}
function summarize(records,ledger,lots,equity,summary={}){const rows=Number(summary.rows_count??records.length),shown=Number(summary.returned_count??records.length),orders=Number(summary.orders_count??records.filter(x=>x.table==='orders').length),fills=Number(summary.fills_count??records.filter(x=>x.table==='fills').length),amount=Number(summary.total_amount||0),pnl=Number(summary.total_pnl||0),positions=Number(summary.positions_count??lots.filter(x=>x.status==='open').length),lastEq=summary.latest_account_value??equity[0]?.equity??equity[0]?.total_equity;const cards=[['全部记录',rows+(shown<rows?'（本页 '+shown+'）':'')],['委托 / 成交',orders+' / '+fills],['实际成交金额',money(amount)],['当前总盈亏',money(pnl)],['当前持仓',positions+' 只'],['最新账户权益',money(lastEq)]];$('summary').innerHTML=cards.map(x=>`<div class="card"><span>${x[0]}</span><b class="${x[0].includes('盈亏')?cls(pnl):''}">${x[1]}</b></div>`).join('')}
function renderRecords(rows){window.data_records=rows;$('recordRows').innerHTML=rows.map(x=>`<tr><td>${esc(x.created_at||x.timestamp||'--')}</td><td>${esc(x.record_type_cn||cn(x.table)||'--')}</td><td>${esc(cn(x.mode))}</td><td>${esc(x.symbol||'--')}</td><td>${esc(cn(x.display_side||x.display_status||x.side||x.status))}</td><td>${money(x.display_price??x.price)}</td><td>${esc(x.display_quantity??x.quantity??'--')}</td><td>${money(x.display_amount??x.amount??x.market_value)}</td><td>${money(x.display_fee??x.fee)}</td><td class="${cls(x.display_pnl??x.pnl)}">${money(x.display_pnl??x.pnl)}</td><td class="${cls(x.display_pnl_pct??x.pnl_pct)}">${pct(x.display_pnl_pct??x.pnl_pct)}</td><td>${money(x.display_cost_price??x.cost_price??x.avg_cost)}</td><td>${esc(cnText(x.display_summary||x.status_reason||x.reason||'--'))}</td></tr>`).join('')||'<tr><td colspan="13">暂无记录</td></tr>'}
function renderLedger(rows){window.data_ledger=rows;$('ledgerRows').innerHTML=rows.map(x=>`<tr><td>${esc(x.occurred_at||x.created_at)}</td><td>${esc(cn(x.mode))}</td><td>${esc(x.session_id||'--')}</td><td>${esc(x.symbol||'--')}</td><td>${esc(cn(x.entry_type))}</td><td>${esc(cn(x.side))}</td><td>${esc(x.quantity??'--')}</td><td>${money(x.price)}</td><td class="${cls(x.amount)}">${money(x.amount)}</td><td>${esc(x.order_id||'--')}</td><td>${esc(x.fill_id||'--')}</td><td>${esc(x.source||'--')}</td></tr>`).join('')||'<tr><td colspan="12">暂无账本记录</td></tr>'}
function renderLots(rows){window.data_lots=rows;$('lotRows').innerHTML=rows.map(x=>`<tr><td>${esc(x.opened_at||'--')}</td><td>${esc(x.closed_at||'--')}</td><td>${esc(x.symbol)}</td><td>${esc(x.original_quantity)}</td><td>${esc(x.remaining_quantity)}</td><td>${money(x.cost_price)}</td><td>${esc(cn(x.status))}</td><td>${esc(x.source_order_id||'--')}</td><td>${esc(x.source_fill_id||'--')}</td><td>${esc(x.session_id||'--')}</td></tr>`).join('')||'<tr><td colspan="10">暂无持仓批次</td></tr>'}
function renderEquity(rows){window.data_equity=rows;$('equityRows').innerHTML=rows.map(x=>`<tr><td>${esc(x.timestamp||x.fetched_at||'--')}</td><td>${esc(cn(x.mode))}</td><td>${esc(x.account_id||'--')}</td><td>${money(x.cash??x.total_cash)}</td><td>${money(x.available_cash)}</td><td>${money(x.position_market_value??x.market_value)}</td><td>${money(x.equity??x.total_equity)}</td><td class="${cls(x.realized_pnl)}">${money(x.realized_pnl)}</td><td class="${cls(x.unrealized_pnl)}">${money(x.unrealized_pnl)}</td><td class="${cls(x.return_pct)}">${pct(x.return_pct)}</td><td>${esc(x.source||'--')}</td></tr>`).join('')||'<tr><td colspan="11">暂无账户快照</td></tr>'}
async function loadAll(btn){const old=btn?.textContent;if(btn){btn.disabled=true;btn.textContent='查询中...'}try{const mode=$('mode').value,base=query({mode}),recordsQ=query({status:$('status').value});const [r,l,o,a]=await Promise.all([api('/api/trading-records?'+recordsQ),api('/api/trading-records/ledger?'+base),api('/api/trading-records/position-lots?'+base),api('/api/trading-records/account-snapshots?'+base)]);const records=r.data||[],ledger=l.data||[],lots=o.data||[],equity=(a.equity_curve||[]).length?a.equity_curve:(a.data||[]);renderRecords(records);renderLedger(ledger);renderLots(lots);renderEquity(equity);summarize(records,ledger,lots,equity,r.summary||{});exportData=window.data_records}catch(e){alert('查询失败：'+e)}finally{if(btn){btn.disabled=false;btn.textContent=old}}}function exportRows(){const blob=new Blob([JSON.stringify(exportData,null,2)],{type:'application/json'}),u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download='交易记录-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}loadAll();</script></body></html>'''
